from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def can(target: int) -> bool:
            if target == 0:
                return True

            moves = m
            extra_visits_from_left = 0

            for i, p in enumerate(points):
                need = (target + p - 1) // p

                if i == n - 1:
                    moves -= max(need - extra_visits_from_left, 0)
                elif need <= extra_visits_from_left:
                    moves -= 1
                    extra_visits_from_left = 0
                else:
                    add = need - extra_visits_from_left
                    moves -= 2 * add - 1
                    extra_visits_from_left = add - 1

                if moves < 0:
                    return False

            return True

        left, right = 0, min(points) * ((m + 1) // 2 + 1)

        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1

        return left
